from collections import Counter

def histogram(test):
    """Given a string representing a space separated lowercase letters, return a dictionary
    of the letter with the most repetition and containing the corresponding count.
    If several letters have the same occurrence, return all of them.

    Example:
    histogram('a b c') == {'a': 1, 'b': 1, 'c': 1}
    histogram('a b b a') == {'a': 2, 'b': 2}
    histogram('a b c a b') == {'a': 2, 'b': 2}
    histogram('b b b b a') == {'b': 4}
    histogram('') == {}

    """
    # Split the input string into a list of characters
    letters = test.split()

    # Use Counter to count occurrences of each letter
    letter_counts = Counter(letters)

    # Find the maximum occurrence and the corresponding letters
    max_occurrence = max(letter_counts.values())
    most_common_letters = [letter for letter, count in letter_counts.items() if count == max_occurrence]

    # Return a dictionary with the most common letters and their count
    return {letter: count for letter, count in zip(most_common_letters, Counter(most_common_letters).values())}
```

